"""Remaining carrot puddings and complete dessert sauces."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'carrot-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def carrot(a):return I('carrot',a,'g','carrots, peeled and trimmed','Use the same weight of a different carrot variety; color and sweetness will change.')
def butter(a):return I('butter',a,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative.')
def stock(a):return I('stock',a,'ml','unsalted prepared beef stock','Use the same volume of unsalted vegetable stock for a different flavor; check other ingredients before treating the whole recipe as vegetarian.')
def onion(a):return I('onion',a,'g','peeled onion','Use the same weight of trimmed leek, rinsing away any grit.')
def salt(a=3):return I('salt',a,'g','fine salt','Reduce or omit, especially if using salted stock.')
def pepper():return I('pepper',.25,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def cayenne():return I('cayenne',.125,'tsp','ground cayenne pepper','Omit for a milder soup.')
def sugar(a):return I('sugar',a,'g','granulated sugar','Use the same weight of caster sugar.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water; water for dough or starch slurry should remain cold.')
def flour(a):return I('flour',a,'g','all-purpose flour','For a sauce, use the same weight of a gluten-free blend labeled for sauces; pastry requires a separate tested gluten-free dough.')
def bread(a):return I('bread',a,'g','plain bread','Use the same weight of gluten-free bread suitable for toasting.')
def oil(a,k='oil'):return I(k,a,'ml','neutral vegetable oil','Use the same volume of refined sunflower or rapeseed oil.')
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g pasteurized liquid yolk per large yolk; omitting yolk changes the recipe.')
def cream(a):return I('cream',a,'ml','heavy cream','Use the same volume of unsweetened plant cream suitable for cooking.')
def celery(a):return I('celery',a,'g','trimmed celery stalks','Use the same weight of peeled celeriac, cut small and cooked until tender.')
def turnip(a):return I('turnip',a,'g','peeled turnip','Use the same weight of peeled rutabaga; allow extra cooking time until tender.')
def add(n,title,y,t,desc,items,steps,notes,category='Side dishes'):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category=category,servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T18:00:00Z',notes=notes+' Missing amounts, yields and timings are modern adaptation estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes quantities, not cooking times. Cool leftovers promptly in shallow containers and refrigerate within 2 hours at 4°C (40°F) or colder.',source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
PUREE='Press the vegetables and their liquid through a coarse sieve into a clean saucepan, or use an immersion blender directly in the deep pan with its head submerged. Do not seal hot soup in a countertop blender.'
def parsley(a=5):return I('parsley',a,'g','fresh parsley, finely chopped','Use the same weight of chives, or omit.')
def milk(a):return I('milk',a,'ml','whole milk','Use the same volume of unsweetened soy milk; flavor differs.')
def rice(a):return I('rice',a,'g','uncooked long-grain white rice','Use the same weight of another white rice; follow its cooking time until tender.')
def eggfinish():return ['Whisk {{yolks}} with {{cream}} in a bowl. Gradually whisk in a little hot soup, then return the mixture to the saucepan.','Stir over low heat until the soup reaches 71°C (160°F), without boiling. Serve promptly.']
def lemon(a,k='lemon'):return I(k,a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
def bay():return I('bay',1,'','dried bay leaf','Omit if unavailable.')
def lard(a):return I('lard',a,'g','food-grade pork lard','Use the same weight of neutral vegetable oil.')
def tk(k):return '{{'+k+'}}'
def roux(prefix,b,f,liquid,liquidname='unsalted prepared chicken stock'):
 return [dict(butter(b),key=prefix+'butter'),dict(flour(f),key=prefix+'flour'),I(prefix+'stock',liquid,'ml',liquidname,'Use the same volume of unsalted vegetable stock; flavor differs.')]
def rouxsteps(p):
 return ['In a separate small saucepan, melt '+tk(p+'butter')+'. Stir in '+tk(p+'flour')+' and cook for 2 minutes without browning. Gradually whisk in '+tk(p+'stock')+' until smooth. Simmer gently for 5 minutes, stirring.']
def veloute(prefix='s',volume=120):
 # A small complete mushroom sauce component, with all output used in its parent.
 q=volume/120
 return roux(prefix,10*q,8*q,120*q)+[I(prefix+'mushroom',25*q,'g','cultivated white mushrooms, finely chopped','Use the same weight of cultivated cremini mushrooms.')]
def veloutesteps(p='s'):
 return ['Melt '+tk(p+'butter')+' in a small pan. Add '+tk(p+'mushroom')+' and cook gently for 5 minutes without browning. Stir in '+tk(p+'flour')+' for 2 minutes, then gradually whisk in '+tk(p+'stock')+'. Simmer for 10 minutes, stirring, until smooth. Press through a fine sieve, discard the mushroom pieces and keep the sauce warm.']

def peas(a):return I('peas',a,'g','shelled green peas, fresh or frozen','Use the same weight of frozen peas, adding them without thawing.')
def cornflour(a):return I('cornflour',a,'g','cornstarch (cornflour)','Use the same weight of arrowroot starch, adding it near the end and heating just until thickened.')
def nutmeg():return I('nutmeg',.125,'tsp','ground nutmeg','Use the same amount of ground mace, or omit.')
def boilsteps(shape='1 cm cubes',time='12–18'):
 return ['Cut {{carrot}} into '+shape+'. Bring {{water}} and {{salt}} to a boil. Add the carrots and simmer for '+time+' minutes until tender when pierced with a fork. Drain well.']

def eggs(a):return I('eggs',a,'','large eggs','Use 50 g pasteurized liquid whole egg per egg when separation is not required.')
def crumbs(a):return I('crumbs',a,'g','plain dry breadcrumbs','Use the same weight of dry crumbs from another plain wheat bread.')
def almond(a):return I('almond',a,'g','finely ground blanched almonds','Use the same weight of finely ground sunflower seeds for a different flavor.')
def grease():return I('grease',5,'g','softened unsalted butter for the dish','Use the same weight of a block-style dairy-free butter alternative.')
def peel(a):return I('peel',a,'g','thin yellow lemon peel, white pith removed, finely shredded','Use the same weight of thin orange peel for a different flavor.')
def separated(r):next(i for i in r['ingredients'] if i['key']=='eggs')['substitution']='Use large pasteurized shell eggs if preferred; the whites must remain separate and able to whip.'
CHILL='Transfer to clean shallow food-safe containers. Cool promptly, cover and refrigerate within 2 hours at 4°C (40°F) or colder. Use within 4 days, or freeze promptly. This is not shelf-stable and must not be stored at room temperature.'

def suet(a):return I('suet',a,'g','food-grade beef suet, membrane removed and finely shredded','Use the same weight of shredded vegetable suet intended for steamed puddings; check whether it contains wheat flour.')
def potato(a):return I('potato',a,'g','peeled potato, finely grated immediately before mixing','Use the same weight of another starchy white potato; do not rinse away its starch.')
def raisins(a):return I('raisins',a,'g','seedless raisins','Use the same weight of sultanas.')
def currants(a):return I('currants',a,'g','dried Zante currants','Use the same weight of chopped raisins; these are dried grapes, not fresh currant berries.')
def brown(a):return I('brownsugar',a,'g','soft light brown sugar','Use the same weight of dark brown sugar for a stronger molasses flavor.')
def plainflour(a):return I('flour',a,'g','all-purpose flour','Use the same weight of plain wheat flour; a gluten-free substitution needs its own tested formula.')
def cinnamon(a=1):return I('cinnamon',a,'tsp','ground cinnamon','Use half the amount of ground allspice for a different flavor.')
def soda(a):return I('soda',a,'tsp','baking soda (bicarbonate of soda)','Use the specified baking soda; baking powder is not an equal replacement.')
def mixedpeel(a):return I('mixedpeel',a,'g','candied orange and lemon peel, finely chopped','Use the same weight of candied orange peel.')
def zest(a=3,k='zest'):return I(k,a,'g','finely grated lemon zest, without white pith','Use the same weight of orange zest for a different flavor.')
def steamitems():return [grease(),I('steamwater',3000,'ml','hot drinking water for the steaming pan','Use hot drinking water, topping up as needed during steaming.')]
def steamstart(size='2-liter'):
 return ['Grease a heatproof '+size+' pudding basin with {{grease}}. Put a trivet in a deep lidded pot and heat {{steamwater}} to a gentle simmer; the water should reach halfway up the filled basin, so adjust the level to suit the pot.']
def steamend(hours):
 return ['Spoon the mixture into the basin, leaving at least 3 cm room for expansion. Cover with a sheet of baking parchment and then foil, both pleated across the center. Tie securely below the rim with kitchen string and make a string handle.','Lower onto the trivet, cover the pot and maintain a gentle simmer for '+hours+'. Check the water every 30 minutes and add boiling water as needed to keep it halfway up the basin; do not let the pan boil dry.','Carefully lift out using oven gloves and the handle. Open the cover away from your face. The center should be firm and a skewer should show no wet batter; for egg-containing puddings, also check at least 71°C (160°F). If still wet, re-cover and steam another 20–30 minutes, then check again. Rest for 10 minutes, loosen the edge and turn onto a warm plate.']
def brandyitems():
 return [water(240,'swater'),I('sbrandy',30,'ml','brandy for the sauce','Use the same volume of apple juice for an alcohol-free sauce.'),I('ssugar',200,'g','granulated sugar for the sauce','Use the same weight of caster sugar.'),I('slemon',15,'ml','lemon juice for the sauce','Use the same volume of lime juice for a different flavor.'),I('syolks',2,'','large pasteurized egg yolks for the sauce','Use 36 g pasteurized liquid egg yolk.')]
def brandysteps():
 return ['For the sauce, put {{swater}}, {{sbrandy}}, {{ssugar}} and {{slemon}} in a heatproof bowl over a pan of gently simmering water, without the bowl touching the water. Stir until the sugar dissolves and the mixture is hot.','Beat {{syolks}} in another bowl. Gradually whisk in the hot liquid, a small amount at a time, then return everything to the heatproof bowl over the water. Stir continuously until it lightly coats a spoon and reaches at least 71°C (160°F), without boiling. Serve promptly. This is a light pouring sauce; it thickens slightly as it cools.']
def harditems():return [I('hsugar',200,'g','caster sugar for the hard sauce','Use the same weight of superfine granulated sugar.'),I('hbutter',113,'g','softened unsalted butter for the hard sauce','Use the same weight of a block-style dairy-free butter alternative.'),zest(3,'hzest')]
def hardsteps():return ['For the hard sauce, beat {{hbutter}} with {{hsugar}} for 5–8 minutes until pale and creamy, scraping the bowl. Beat in {{hzest}}. Spoon into a small dish and chill until firm; serve small spoonfuls beside the warm pudding. The fine sugar gives this traditional butter sauce a slight granular texture.']

# Two complete companion recipes from the same source book as the later puddings.
for sid,title,items,steps,desc,notes,y,t in [
 ('historical-126e2a2489d2fc454322dae5','Brandy and Lemon Pudding Sauce',brandyitems(),brandysteps(),'A light, sweet brandy-lemon sauce is gently thickened with egg yolks for pouring over warm puddings.','The undefined quarter-glass of brandy becomes a modern 30 ml; the cup of water is 240 ml, sugar 200 g and half-lemon juice 15 ml. A measured cooked-yolk finish completes the original off-heat thickening instruction. Alcohol remains after this short heating; choose the apple-juice substitution if avoiding alcohol.',12,20),
 ('historical-a25b8a37074da3e54103b87f','Lemon Hard Sauce',harditems(),hardsteps(),'Lemon zest brightens a firm, whipped butter-and-sugar accompaniment that softens against warm pudding.','The original cup of sugar and half-cup butter become 200 g and 113 g. Fine granulated sugar is chosen to retain the original ratio with a less coarse texture. Zest, beating and chilling times are modern choices.',16,40)]:
 rows.append({'id':sid});r=add(len(rows)-1,title,y,t,desc,items,steps,notes,'Dessert sauces')

r=add(8,'Carrot, Potato and Fruit Pudding with Brandy Sauce',12,225,'Carrot and potato keep this steamed fruit-and-suet pudding moist; candied peel and warm spices flavor the dense crumb.',[carrot(110),potato(150),brown(200),suet(110),raisins(180),currants(180),eggs(1),mixedpeel(30),plainflour(150),soda(1),salt(1),cinnamon(.5),nutmeg()]+steamitems()+brandyitems(),steamstart()+['Mix {{flour}}, {{soda}}, {{salt}}, {{cinnamon}} and {{nutmeg}}. Stir in {{suet}}, {{raisins}}, {{currants}} and {{mixedpeel}}.','Finely grate {{carrot}}. Beat {{eggs}} with {{brownsugar}}, then stir in the carrot and freshly grated {{potato}}, keeping their juices. Fold into the dry ingredients to make a thick, moist mixture.']+steamend('3 hours')+brandysteps()+['Serve the warm pudding with the sauce.'],'The original printed page 202 genuinely contains no flour or bread. This adaptation explicitly adds 150 g flour for structure; it is not a recovered historical amount. Modern preparation weights replace cup volumes and undefined large cups. Spice and peel are specified. The full brandy sauce is a disclosed companion adapted from Greenbaum 1918, not a claim to recover Denison’s exact intended sauce. Alcohol remains in the sauce unless the apple-juice substitution is used.','Desserts')
r['source']+=' Primary scan checked: Canadian Family Cook Book, printed page 202, leaf 226. Sauce component: The International Jewish Cook Book (1918), https://archive.org/details/cu31924003580952 .'

r=add(9,'Molasses Carrot and Potato Pudding',12,225,'Molasses sweetens a dense steamed pudding of grated carrot, potato, suet and dried fruit, served with sweet melted butter.',[plainflour(150),suet(110),I('molasses',320,'g','mild unsulphured molasses','Use the same weight of dark treacle for a different flavor; avoid bitter blackstrap molasses.'),potato(150),carrot(110),currants(150),raisins(150),salt(1),soda(.125)]+steamitems()+[I('sbutter',60,'g','unsalted butter for serving','Use the same weight of a block-style dairy-free butter alternative.'),I('ssugar',30,'g','caster sugar for serving','Use the same weight of fine granulated sugar.'),water(30,'swater')],steamstart()+['Mix {{flour}}, {{salt}} and {{soda}}, then stir in {{suet}}, {{currants}} and {{raisins}}. Finely grate {{carrot}} and combine with freshly grated {{potato}} and {{molasses}}, retaining the vegetable juices. Mix everything into a thick, moist batter.']+steamend('3 hours')+['For the sweet butter, heat {{swater}} with {{ssugar}} in a small pan until dissolved. Remove from the heat and whisk in diced {{sbutter}} until melted.','Serve the warm pudding with the warm sweet butter.'],'Cup measures become modern weighed quantities: flour 150 g, suet 110 g, molasses 320 g, carrot 110 g, potato 150 g and dried fruits 150 g each. The source pinch of soda becomes ⅛ teaspoon. The sweet-melted-butter accompaniment is fully supplied. No eggs are added to this distinct source formula.','Desserts')

r=add(10,'Brown-Sugar Carrot and Potato Pudding',12,280,'A dense, egg-free steamed pudding combines grated vegetables, suet and dried fruit with soft brown sugar.',[potato(150),carrot(110),suet(110),raisins(150),currants(150),brown(200),plainflour(210),soda(1),water(60)]+steamitems(),steamstart()+['Mix {{flour}} with {{soda}}. Stir in {{suet}}, {{raisins}} and {{currants}}. Finely grate {{carrot}} and combine with freshly grated {{potato}}, {{brownsugar}} and {{water}}, retaining the vegetable juices. Fold into the dry ingredients to make a thick, moist mixture.']+steamend('4 hours')+['Serve warm, cut into small portions.'],'The yellow sugar is interpreted as soft light brown sugar. Cup volumes become disclosed preparation weights. A measured 60 ml water is supplied because the source gives no liquid and grated-vegetable moisture varies. Four-hour steaming is retained, with a complete covered-basin method. This has more flour and a different sweetener from the molasses pudding and is kept separately.','Desserts')

r=add(67,'Rich Carrot and Fruit Pudding with Brandy Sauce',10,230,'A rich carrot pudding combines suet, raisins, currants and nutmeg with egg yolks and ale, finished with a sweet brandy sauce.',[plainflour(113),suet(113),carrot(113),raisins(113),currants(113),sugar(227),eggs(1),yolks(2),I('ale',70,'ml','ale','Use the same volume of alcohol-free malt drink for a different flavor.'),nutmeg()]+steamitems()+brandyitems(),steamstart('1.5-liter')+['Mix {{flour}}, {{suet}}, {{raisins}}, {{currants}}, {{sugar}} and {{nutmeg}}. Finely grate {{carrot}} and stir in. Beat {{eggs}} and {{yolks}} with {{ale}}, then fold into the dry ingredients.']+steamend('3 hours')+brandysteps()+['Serve the pudding warm with the sauce.'],'The original large batch is halved: half-pound ingredients become 113 g, one pound sugar 227 g, two eggs become one and four extra yolks become two. Half an Imperial gill becomes 70 ml. The original one-hour boil is replaced explicitly with a three-hour covered steam and a doneness check. A full baked variation preserves its other cooking option. Brandy sauce is a disclosed modern companion based on Greenbaum 1918. Alcohol may remain; use both alcohol-free substitutions if avoiding it.','Desserts')
vitems=[copy.deepcopy(i) for i in r['ingredients'] if i['key']!='steamwater'];vsteps=['Heat the oven to 160°C (320°F). Grease a 1.5-liter baking dish with {{grease}}.',r['steps'][1],'Spoon into the dish and bake for 75–100 minutes until firm in the center, a skewer shows no wet batter and the center reaches at least 71°C (160°F). Cover loosely with foil if the top darkens before the center is ready. Rest for 15 minutes.']+brandysteps()+['Serve warm with the sauce.'];variant(r,'baked','Baked carrot and fruit pudding',vitems,vsteps)
r['source']+=' Sauce component: Greenbaum 1918, https://archive.org/details/cu31924003580952 .'

r=add(71,'Carrot-Almond Suet Pudding with Brandy Sauce',10,220,'Ground almonds, carrot and citrus peel make a rich steamed pudding with a firm, moist crumb and a sweet pouring sauce.',[carrot(85),crumbs(85),mixedpeel(28),suet(85),eggs(4),almond(227),sugar(85),I('coatsugar',10,'g','caster sugar for coating the basin','Use the same weight of fine granulated sugar.')]+steamitems()+brandyitems(),steamstart('1.5-liter')+['Swirl {{coatsugar}} around the greased basin to coat it. Finely grate {{carrot}}. Mix with {{crumbs}}, {{mixedpeel}}, {{suet}}, {{almond}} and {{sugar}}. Beat {{eggs}} and mix into the dry ingredients until evenly combined.']+steamend('3 hours')+brandysteps()+['Serve warm with the sauce.'],'The large source formula is halved: six-ounce ingredients become 85 g, two ounces peel 28 g, one pound almonds 227 g and eight eggs become four. The undefined orange-and-lemon peel is interpreted as candied peel for this sweet pudding. Basin coating and sauce are fully quantified. Its almond-rich formula remains distinct from the flour-and-fruit pudding. Brandy sauce is a disclosed companion adapted from Greenbaum 1918; use apple juice if avoiding alcohol.','Desserts')
r['source']+=' Sauce component: Greenbaum 1918, https://archive.org/details/cu31924003580952 .'

r=add(72,'Spiced Carrot and Potato Pudding with Lemon Hard Sauce',12,280,'Cinnamon, cloves and allspice flavor a steamed carrot-and-potato pudding enriched with butter, dried fruit and whiskey.',[sugar(200),butter(76),carrot(110),potato(150),raisins(150),currants(150),I('crumbs',180,'g','finely grated fresh white breadcrumbs','Use the same weight of fresh crumbs from another plain white wheat loaf.'),soda(.5),I('cloves',1,'tsp','ground cloves','Use half the amount for a milder spice flavor.'),cinnamon(),I('allspice',1,'tsp','ground allspice','Use half the amount of ground nutmeg for a different flavor.'),I('syrup',30,'g','golden syrup','Use the same weight of mild molasses for a darker flavor.'),I('whiskey',60,'ml','whiskey','Use the same volume of apple juice for an alcohol-free ingredient choice.')]+steamitems()+harditems(),steamstart()+['Beat softened {{butter}} with {{sugar}}. Finely grate {{carrot}} and add with freshly grated {{potato}}, retaining their juices. Stir in {{raisins}}, {{currants}}, {{crumbs}}, {{soda}}, {{cloves}}, {{cinnamon}}, {{allspice}}, {{syrup}} and {{whiskey}} until evenly combined.']+steamend('4 hours')+hardsteps()+['Serve small slices of the warm pudding with the chilled hard sauce.'],'Cup measurements become modern preparation weights; breadcrumbs are specified as fresh. A little syrup becomes 30 g golden syrup and four tablespoons whiskey become 60 ml. The full hard sauce is recovered from the same book and included here. Source spice amounts and four-hour steaming are retained. Cooking does not guarantee all alcohol has evaporated; choose apple juice if avoiding it.','Desserts')

r=add(73,'Carrot-Almond Egg Pudding',10,105,'Whipped egg whites lighten a sweet baked carrot-and-almond pudding scented with lemon and a little white wine.',[I('icing',180,'g','powdered sugar (icing sugar), sifted','Use the same weight of another plain icing sugar.'),eggs(8),carrot(165),almond(100),zest(),I('wine',15,'ml','white wine','Use the same volume of apple juice if avoiding alcohol.'),grease(),I('coatflour',10,'g','all-purpose flour for the pan','Use the same weight of rice flour for coating.')],['Heat the oven to 150°C (300°F). Grease a 23 cm round, deep baking dish with {{grease}} and dust with {{coatflour}}, tapping out excess. Finely grate {{carrot}}.','Separate {{eggs}} into clean bowls. Beat the yolks with {{icing}} for 4–5 minutes until thick and pale. Stir in the carrot, {{almond}}, {{zest}} and {{wine}}.','With clean beaters, whip the egg whites to soft peaks. Fold one-third into the carrot mixture to loosen it, then gently fold in the rest. Pour into the prepared dish.','Bake for 60–75 minutes until set, lightly browned and at least 71°C (160°F) in the center. Avoid opening the oven early. Rest for 15 minutes before serving in the dish; some settling is normal.'],'Modern cup weights are 120 g per cup powdered sugar, 110 g per cup grated carrot and 100 g per cup ground almonds. The eight separated eggs are retained. Pan preparation, temperature and doneness are supplied. This is a baked egg pudding, not a flour-based carrot cake. Alcohol may remain unless the apple-juice substitution is used.','Desserts');separated(r)

r=add(74,'Carrot Schalet with Cinnamon',6,125,'Cooked grated carrots bake with eggs, chicken fat and lemon into a light, gently sweet pudding with a cinnamon-sugar top.',[carrot(454),water(1500),I('fat',20,'g','rendered chicken fat (schmaltz), softened','Use the same weight of neutral vegetable oil for a different flavor.'),sugar(50),eggs(4),zest(6),cinnamon(),nutmeg(),plainflour(24),I('bakingpowder',1,'tsp','baking powder','Use the same amount of another plain baking powder.'),salt(1),I('panfat',25,'g','rendered chicken fat for the dish','Use the same weight of neutral vegetable oil.'),I('topsugar',10,'g','granulated sugar for topping','Use the same weight of caster sugar.'),I('topcinnamon',.25,'tsp','ground cinnamon for topping','Omit for a milder topping.')],['Put {{carrot}} whole in a saucepan with {{water}}. Simmer for 20–30 minutes until tender. Drain, spread on a shallow plate and cool until no longer warm, then grate.','Heat the oven to 175°C (350°F). Separate {{eggs}}. Beat {{fat}} with {{sugar}}, then beat in the yolks one at a time. Stir in the carrot, {{zest}}, {{cinnamon}}, {{nutmeg}}, {{flour}}, {{bakingpowder}} and {{salt}}.','Using clean beaters, whip the whites to soft peaks and fold into the carrot mixture. Put {{panfat}} in a 1.5-liter metal or ceramic oven-safe dish and warm in the oven for 3 minutes, just until melted. Carefully swirl to coat.','Pour in the mixture and bake for 45–60 minutes until set and at least 71°C (160°F) in the center. Mix {{topsugar}} and {{topcinnamon}}, sprinkle over the pudding and return to the oven for 3–5 minutes. Serve hot.'],'A heaped spoon of chicken fat becomes 20 g; the few spoons of fat for the dish are moderated to 25 g. Three tablespoons flour become 24 g and four tablespoons sugar 50 g. The four yolks and their beaten whites remain part of the same four eggs. Separate topping quantities complete the final instruction. No dairy ingredients are introduced.','Desserts');separated(r)

r=add(136,'Carrot and Dried-Fruit Pudding',8,235,'Cooked carrot purée moistens a breadcrumb-and-suet pudding with raisins, currants and nutmeg, served steamed or baked.',[carrot(340),water(1000),crumbs(227),suet(113),raisins(113),currants(113),sugar(85),eggs(3),milk(120),nutmeg(),I('dustsugar',10,'g','powdered sugar for serving','Use the same weight of caster sugar for a different finish.')]+steamitems(),['Cut {{carrot}} into small pieces. Simmer in {{water}} for 15–20 minutes until very tender. Drain thoroughly, mash smoothly and spread in a shallow bowl to cool until no longer warm.']+steamstart()+['Mix {{crumbs}}, {{suet}}, {{raisins}}, {{currants}}, {{sugar}} and {{nutmeg}}. Beat {{eggs}} with {{milk}} and stir in with the cooled carrot mash to make a thick batter.']+steamend('2½ hours')+['Dust with {{dustsugar}} and serve warm.'],'The source weight ratios are retained using rounded grams. Undefined milk becomes 120 ml; a quarter nutmeg is moderated to ⅛ teaspoon ground nutmeg. The original cloth-covered boil becomes a securely covered basin steamed in a lidded pot. A full baked version preserves the other source method.','Desserts')
vitems=[copy.deepcopy(i) for i in r['ingredients'] if i['key']!='steamwater'];vsteps=[r['steps'][0],'Heat the oven to 175°C (350°F). Grease a 2-liter baking dish with {{grease}}.',r['steps'][2],'Spread the batter in the dish and bake for 55–75 minutes until firm in the center, a skewer shows no wet batter and the center reaches at least 71°C (160°F). Cover loosely with foil if browning too quickly. Rest for 15 minutes, dust with {{dustsugar}} and serve in the dish.'];variant(r,'baked','Baked carrot and dried-fruit pudding',vitems,vsteps)

r=add(148,'Möhrenkoch (Rich Carrot and Egg Pudding)',6,105,'Finely grated carrot is cooked with a little egg, then baked with more egg, butter and soaked bread into a rich Austrian pudding.',[carrot(250),I('firstegg',62.5,'g','beaten whole egg for cooking with the carrots','Use the same weight of pasteurized liquid whole egg.'),I('secondegg',137.5,'g','beaten whole egg for the pudding mixture','Use the same weight of pasteurized liquid whole egg.'),I('yolkweight',45,'g','beaten pasteurized egg yolk','Use the same weight of pasteurized liquid egg yolk.'),butter(50),I('roll',35,'g','plain white bread roll, crust removed','Use the same weight of plain white bread.'),milk(100),sugar(85),grease()],['Heat the oven to 150°C (300°F). Grease a 1-liter baking dish with {{grease}}. Tear {{roll}} into pieces and soak in {{milk}} for 10 minutes, then squeeze gently over a bowl; discard the excess soaking milk.','Finely grate {{carrot}}. Put in a nonstick pan over medium-low heat and stir for 8–12 minutes until softened and visible surface moisture has evaporated; do not brown. Add {{firstegg}} and stir until fully set and at least 71°C (160°F). Spread in a shallow bowl and cool until no longer warm.','Beat the cooled carrot mixture until smooth. Beat in melted and cooled {{butter}}, followed gradually by {{secondegg}}, {{yolkweight}}, the squeezed bread and {{sugar}}. Beat for 3–5 minutes until evenly combined.','Pour into the prepared dish and bake for 45–60 minutes until set and at least 71°C (160°F) in the center. If the top darkens early, cover loosely with foil. Rest for 15 minutes and serve warm, or cool promptly and refrigerate before serving cold.'],'The original scan confirms five whole eggs cooked with carrot, followed by eleven whole eggs and ten yolks: these are not fraction errors. This modern smaller version uses one-quarter of those egg quantities by weight, assuming 50 g per whole egg and 18 g per yolk; weigh the two whole-egg portions from 200 g beaten egg. Missing carrot, butter and bread amounts are supplied. Sugar is a chosen 85 g modern amount, not a verified conversion of the Austrian historical pound. Fifteen-minute hand mixing becomes 3–5 minutes of beating.','Desserts')
r['source']+=' Primary scan checked: Anna Dorn 1825, recipe 517, printed page 230, leaf 312.'

pastry=copy.deepcopy(records[rows[3]['id']]['recipe'])
pastryitems=[i for i in pastry['ingredients'] if i['key'] in ['pastryflour','pastrybutter','pastrywater','pastrysalt','dustflour']]
filling=[carrot(85),water(240),sugar(200),yolks(2),I('whites',2,'','large pasteurized egg whites','Use pasteurized shell eggs whose whites can whip; liquid products must be labeled suitable for whipping.'),butter(15),cornflour(16),I('vanilla',2.5,'ml','vanilla extract','Use the same volume of vanilla bean paste.'),salt(1)]
piesteps=[pastry['steps'][0],'Heat the oven to 190°C (375°F). Roll the chilled pastry on {{dustflour}} to about 3 mm thick and line a 23 cm pie dish. Trim, prick the base, line with baking parchment and fill with reusable baking weights.','Bake for 15 minutes. Carefully remove the parchment and weights, then bake for 10–15 minutes until the shell is dry and lightly golden. Leave in the dish.']
fillsteps=['Finely grate {{carrot}}. Put in a small pan with {{water|0.75}}, cover and simmer for 10–15 minutes until very soft. Mash finely, keeping the cooking liquid.','Mix {{cornflour}} with {{water|0.25}} until smooth. Stir into the hot carrot along with {{sugar|0.625}} and {{salt}}. Bring to a gentle boil, stirring constantly, and cook for 1 minute until thickened.','Beat {{yolks}} in a bowl. Gradually whisk in a few spoonfuls of hot filling, then return everything to the pan. Stir over low heat until at least 71°C (160°F), without boiling. Remove from heat and stir in {{butter}} and {{vanilla}}. Spread in the prepared base.','Put {{whites}} and {{sugar|0.375}} in a clean heatproof bowl over gently simmering water, with the bowl above the water. Whisk constantly until the sugar dissolves and the mixture reaches 71°C (160°F). Remove from the pan and beat with clean electric beaters until glossy, stiff peaks form.','Spread the meringue over the filling to meet the edges. Bake at 190°C (375°F) for 5–8 minutes until the tips are lightly golden. Watch closely to avoid burning. Cool on a rack, refrigerate within 2 hours and chill for at least 2 hours before slicing.']
r=add(5,'Carrot Custard Meringue Pie',8,240,'A light carrot-and-vanilla custard fills a crisp pastry shell beneath a softly browned meringue topping.',pastryitems+filling,piesteps+fillsteps,'The two records reproduce the same sugar, carrot, water, egg, butter and cornstarch formula; the shorter transcription omits the longer record’s whipped-white topping instruction. The original two eggs are separated into two yolks and two whites. The 200 g sugar is deliberately divided: 125 g for custard and 75 g for a cooked meringue. Full pastry, custard cooking and chilled setting replace the reference to lemon pie. The source alternative of a light-cake bottom is retained as a named variation.','Desserts')
variant(r,'cake-base','Carrot custard on a light cake base',[I('cake',220,'g','prepared plain sponge cake, sliced into a 2 cm-thick layer','Use the same weight of plain prepared angel-food cake for a lighter base.')]+copy.deepcopy(filling),['Arrange {{cake}} in the bottom of a 23 cm oven-safe pie dish, trimming and fitting the pieces into an even layer. Heat the oven to 190°C (375°F).']+copy.deepcopy(fillsteps))
merges=[(6,5,'Identical formula and lemon-pie shorthand from the same book. The longer record supplies the whipped-white topping; both explicitly allow a pie-shell or light-cake base, preserved as full named variations.')]
